const canvas = document.getElementById('studioCanvas');
    const ctx = canvas.getContext('2d');

    function resizeCanvas() {
      const rect = canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.scale(dpr, dpr);
    }
    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    let mouse = { x: 400, y: 200, inside: false };
    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      mouse.x = e.clientX - rect.left;
      mouse.y = e.clientY - rect.top;
      mouse.inside = true;
    });
    canvas.addEventListener('mouseleave', () => { mouse.inside = false; });

    let currentViewMode = "FRONT";
    let currentEnvMode = "LIVING_ROOM"; // Default to Cozy Living Room!

    function updateStatusPill() {
      const envName = currentEnvMode === "LIVING_ROOM" ? "Cozy Living Room" : (currentEnvMode === "PARK" ? "Sunny Park" : "Studio Stage");
      const viewName = currentViewMode === "PROFILE" ? "3/4 Profile" : "Front View";
      const pill = document.getElementById('statusPill');
      pill.textContent = `Setting: ${envName} • Perspective: ${viewName} • ⚡ Neural Audio • v5.0`;
      if (currentEnvMode === "LIVING_ROOM") {
        pill.className = "absolute top-3 right-4 text-xs font-mono text-amber-300 bg-slate-950/85 px-3.5 py-1 rounded-full border border-amber-500/40 backdrop-blur pointer-events-none shadow-md z-10";
      } else if (currentEnvMode === "PARK") {
        pill.className = "absolute top-3 right-4 text-xs font-mono text-emerald-300 bg-slate-950/85 px-3.5 py-1 rounded-full border border-emerald-500/40 backdrop-blur pointer-events-none shadow-md z-10";
      } else {
        pill.className = "absolute top-3 right-4 text-xs font-mono text-cyan-300 bg-slate-950/85 px-3.5 py-1 rounded-full border border-cyan-500/40 backdrop-blur pointer-events-none shadow-md z-10";
      }
    }

    // View Switcher Listeners
    document.getElementById('btnViewProfile').addEventListener('click', () => {
      currentViewMode = "PROFILE";
      document.getElementById('btnViewProfile').className = "view-btn px-3 py-1.5 rounded-lg text-xs font-bold bg-pink-600 text-white transition flex items-center gap-1.5 shadow-sm";
      document.getElementById('btnViewFront').className = "view-btn px-3 py-1.5 rounded-lg text-xs font-medium text-slate-400 hover:text-white transition flex items-center gap-1.5";
      updateStatusPill();
    });

    document.getElementById('btnViewFront').addEventListener('click', () => {
      currentViewMode = "FRONT";
      document.getElementById('btnViewFront').className = "view-btn px-3 py-1.5 rounded-lg text-xs font-bold bg-pink-600 text-white transition flex items-center gap-1.5 shadow-sm";
      document.getElementById('btnViewProfile').className = "view-btn px-3 py-1.5 rounded-lg text-xs font-medium text-slate-400 hover:text-white transition flex items-center gap-1.5";
      updateStatusPill();
    });

    // Environment Switcher Listeners
    const btnEnvLivingRoom = document.getElementById('btnEnvLivingRoom');
    const btnEnvPark = document.getElementById('btnEnvPark');
    const btnEnvStudio = document.getElementById('btnEnvStudio');

    function setEnvironment(env) {
      currentEnvMode = env;
      btnEnvLivingRoom.className = (env === "LIVING_ROOM") ? "env-btn px-3 py-1.5 rounded-lg text-xs font-bold bg-amber-600 text-white transition flex items-center gap-1.5 shadow-sm" : "env-btn px-3 py-1.5 rounded-lg text-xs font-medium text-slate-400 hover:text-white transition flex items-center gap-1.5";
      btnEnvPark.className = (env === "PARK") ? "env-btn px-3 py-1.5 rounded-lg text-xs font-bold bg-emerald-600 text-white transition flex items-center gap-1.5 shadow-sm" : "env-btn px-3 py-1.5 rounded-lg text-xs font-medium text-slate-400 hover:text-white transition flex items-center gap-1.5";
      btnEnvStudio.className = (env === "STUDIO") ? "env-btn px-3 py-1.5 rounded-lg text-xs font-bold bg-cyan-600 text-white transition flex items-center gap-1.5 shadow-sm" : "env-btn px-3 py-1.5 rounded-lg text-xs font-medium text-slate-400 hover:text-white transition flex items-center gap-1.5";
      updateStatusPill();
    }

    btnEnvLivingRoom.addEventListener('click', () => setEnvironment("LIVING_ROOM"));
    btnEnvPark.addEventListener('click', () => setEnvironment("PARK"));
    btnEnvStudio.addEventListener('click', () => setEnvironment("STUDIO"));

    function push() { ctx.save(); }
    function pop() { ctx.restore(); }
    function translate(x, y) { ctx.translate(x, y); }
    function rotate(a) { ctx.rotate(a); }

